(()=>{'use strict';const season=location.pathname.split('/')[2]||'autumn';window.Reference14=season==='autumn';const C=QingchiCore,L=QingchiLifeCore;if(!localStorage.getItem(C.KEY)){const s=C.initial();s.settings.fishCount=24;s.settings.quietView=true;localStorage.setItem(C.KEY,JSON.stringify(s));}let s=localStorage.getItem(L.KEY)?L.validate(JSON.parse(localStorage.getItem(L.KEY))):L.initial();s.garden=[];s.habitats.layouts.clear=[];s.habitats.active='clear';s.habitats.visitors={enabled:false,density:'low'};s.env={season:['spring','summer','autumn'].includes(season)?season:'autumn',light:'day',weather:'clear'};localStorage.setItem(L.KEY,JSON.stringify(L.validate(s)));addEventListener('DOMContentLoaded',()=>{document.title=(location.port==='8814'?'清爽与遮挡修正16':'已选基线')+' · '+({spring:'春',summer:'夏',autumn:'秋'}[season]);});})();